-- IPS Project 5.7 municipality data part 2
-- Current municipality identity set: 7,894 rows. Existing friendly IPS city codes are preserved.

begin;

on conflict (istat_code) do update set
  code=public.cities.code,
  name=excluded.name,
  region=excluded.region,
  country_code=excluded.country_code,
  status='ACTIVE',
  cadastral_code=excluded.cadastral_code,
  alternate_name=excluded.alternate_name,
  province_name=excluded.province_name,
  province_code=excluded.province_code,
  province_abbr=excluded.province_abbr,
  region_code=excluded.region_code,
  source_updated_on=excluded.source_updated_on,
  updated_at=now();
commit;
